expected:
:root, :host {
  --color-black: #000;
}

@layer utilities {
  .flex {
    display: flex;
  }

  @media (hover: hover) {
    .hover\:underline:hover {
      text-decoration-line: underline;
    }
  }

  @media (min-width: 768px) {
    .md\:grid {
      display: grid;
    }
  }

  @media (prefers-color-scheme: dark) {
    .dark\:bg-black {
      background-color: var(--color-black);
    }
  }
}

`@theme` blocks must only contain custom properties or `@keyframes`.

  @theme {
>   .foo {
>     --color-primary: blue;
>   }
  }

.flex {
  display: flex;
}

.grid {
  display: grid;
}

